const apiResponse = $input.first().json.body || $input.first().json;
const inputData = $('Validate Input').first().json;

return [{
  json: {
    success: true,
    subscriber_id: apiResponse.id || apiResponse.subscriber_id || 'created',
    credits: inputData.initial_credits,
    plan: inputData.plan_id,
    message: 'Abonnement cree avec succes'
  }
}];

const apiResponse = $input.first().json;
const statusCode = apiResponse.statusCode || 500;
const body = apiResponse.body || {};

// Check if already subscribed (409 or specific error)
if (statusCode === 409 || body.error === 'already_exists') {
  return [{
    json: {
      success: false,
      error: 'already_subscribed',
      message: "L'utilisateur est deja abonne",
      statusCode: 409
    }
  }];
}

return [{
  json: {
    success: false,
    error: body.error || 'api_error',
    message: body.message || 'Erreur lors de la creation',
    statusCode: statusCode
  }
}];
